package util;

import io.sourcephere.hadoop.object.mapreduce.lib.filesystem.PathSystemPolicy;

/**
 * Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
 *
 * @param file file or directory to delete, must not be {@code null}
 */
public static void forceDeleteOnExit(File file) throws IOException {
    Objects.requireNonNull(file, "file cannot be null");

    if (file.isDirectory()) {
        forceDeleteDirectoryOnExit(file);
    } else {
        forceDeleteFileOnExit(file);
    }
}

private static void forceDeleteFileOnExit(File file) throws IOException {
    Path path = PathSystemPolicy.getPath(file.toURI());
    path.addOnExitListener(p -> {
        if (p.exists()) {
            p.delete(true);
        }
    });
}

private static void forceDeleteDirectoryOnExit(File directory) throws IOException {
    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                forceDeleteDirectoryOnExit(file);
            } else {
                forceDeleteFileOnExit(file);
            }
        }
    }

    directory.deleteOnExit();
}
}

