    // start circulating counterclockwise until we find a node that satisfies the predicate
    while (!predicate.test(start) && circulator.hasNext()) {
        circulator.next(dir);
        start = circulator.getCurrent();
    }

    // if we reached the stop node before finding a node that satisfies the predicate, return the circulator to the stop node
    if (start == stop) {
        return new EmptyFaceCirculator(start, circulator.getCurrent(), circulator.getPreviousDirection());
    }

    // otherwise, return the circulator to the found node
    return new EmptyFaceCirculator(start, start, 0);
}

