public static boolean startsWith(String str, String prefix, boolean ignoreCase) {
    if (str == null || prefix == null) {
        return str == null && prefix == null;
    }
    int toffset = 0;
    int poffset = 0;
    int strLen = str.length();
    int prefLen = prefix.length();
    if (prefLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        while (toffset < strLen && poffset < prefLen && str.charAt(toffset) == prefix.charAt(poffset)) {
            toffset++;
            poffset++;
        }
        return poffset == prefLen;
    } else {
        return str.substring(toffset, toffset + prefLen).equals(prefix);
    }
}
