public static void selectRow(int row, JTable table, JScrollPane pane) {
    table.setRowSelectionInterval(row, row);
    Rectangle cellRect = table.getCellRect(row, 0, true);
    int midPoint = (int) (cellRect.getHeight() / 2);
    JViewport viewport = pane.getViewport();
    int difference = cellRect.y - viewport.getViewPosition().y;
    if (Math.abs(difference) < midPoint) {
      pane.getVerticalScrollBar().setValue(cellRect.y - midPoint);
    } else {
      pane.getVerticalScrollBar().setValue(cellRect.y + cellRect.height - pane.getHeight());
    }
    table.repaint();
  }

