public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Get the bounds of the type variable
    Type[] bounds = typeVariable.getBounds();

    // If the type variable has no bounds, return Unknown.class
    if (bounds.length == 0) {
        return Unknown.class;
    }

    // Get the first bound
    Type firstBound = bounds[0];

    // If the first bound is a class, return it
    if (firstBound instanceof Class<?>) {
        return (Class<?>) firstBound;
    }

    // If the first bound is a parameterized type, get the raw type
    if (firstBound instanceof ParameterizedType) {
        return ((ParameterizedType) firstBound).getRawType();
    }

    // If the first bound is an array type, get the component type
    if (firstBound instanceof GenericArrayType) {
        return ((GenericArrayType) firstBound).getGenericComponentType();
    }

    // If none of the above conditions are true, return Unknown.class
    return Unknown.class;
}

public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Check if the type variable has an explicit bound
    Type bound = typeVariable.getBounds()[0];
    if (bound != null) {
        return TypeUtils.getRawType(bound);
    }

    // Check if the type variable is a type parameter for a generic class declaration
    TypeVariable<?>[] typeParams = typeVariable.getGenericDeclaration().getTypeParameters();
    for (TypeVariable<?> typeParam : typeParams) {
        if (typeParam.equals(typeVariable)) {
            return Unknown.class;
        }
    }

    // Check if the type variable is a type parameter for a generic method declaration
    TypeVariable<?>[] methodTypeParams = typeVariable.getGenericDeclaration().getTypeParameters();
    for (TypeVariable<?> methodTypeParam : methodTypeParams) {
        if (methodTypeParam.equals(typeVariable)) {
            return Unknown.class;
        }
    }

    // The type variable has no bounds, so return Unknown.class
    return Unknown.class;
}

