public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check that the given vertices form a valid subgraph
    if (vertices.size() < 2) {
        return false;
    }

    // Check that all vertices are valid
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
    }

    // Check that the induced subgraph is complete
    for (V vertex : vertices) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

